41	impl<'a> Macros<'a> {
42	  pub fn new(
43	    callback: MacroCallback,
44	    source_map: &'a SourceMap,
45	    diagnostics: &'a mut Vec<Diagnostic>,
46	  ) -> Self {
47	    Macros {
48	      macros: HashMap::new(),
