170	  fn fold_expr(&mut self, node: Expr) -> Expr {
171	    if let Expr::Call(call) = node {
172	      if let Callee::Expr(expr) = &call.callee {
173	        match &**expr {
174	          Expr::Ident(ident) => {
175	            if let Some(specifier) = self.macros.get(&ident.to_id()) {
176	              if let Some(imported) = &specifier.imported {
177	                let specifier = specifier.src.to_string();
178	                let imported = imported.to_string();
179	                let call = call.fold_with(self);
180	                return handle_error(
181	                  self.call_macro(specifier, imported, call),
182	                  &mut self.diagnostics,
183	                );
184	              }
185	            }
186	          }
187	          Expr::Member(member) => {
188	            // e.g. ns.macro()
189	            if let Expr::Ident(ident) = &*member.obj {
190	              if let (Some(specifier), Some(prop)) = (
191	                self.macros.get(&ident.to_id()),
192	                match_property_name(&member),
193	              ) {
194	                // Check that this is a namespace import.
195	                if specifier.imported.is_none() {
196	                  let specifier = specifier.src.to_string();
197	                  let imported = prop.0.to_string();
198	                  let call = call.fold_with(self);
199	                  return handle_error(
200	                    self.call_macro(specifier, imported, call),
201	                    &mut self.diagnostics,
202	                  );
203	                }
204	              }
205	            }
206	          }
207	          _ => {}
208	        }
209	      }
210	
211	      // Not a macro. Track if we're in a call so we can error if constant
212	      // objects are referenced that might be mutated.
213	      self.in_call = true;
214	      let call = call.fold_with(self);
215	      self.in_call = false;
216	      return Expr::Call(call);
217	    }
218	
219	    node.fold_children_with(self)
220	  }
